--- a/autoscaler/core/tokenbucket.go
+++ b/autoscaler/core/tokenbucket.go
@@ -120,6 +120,28 @@ func (tb *TokenBucket) addTokens(delta int) {
+// exponential decay smoothing: new = alpha*sample + (1-alpha)*old
+tb.smoothed = tb.alpha*sample + (1-tb.alpha)*tb.smoothed
+// cap carryover to prevent runaway bursts
+if tb.smoothed > tb.carryoverCap {
+  tb.smoothed = tb.carryoverCap
+}
